import org.mockito.MockedStatic;

import javax.sql.DataSource;
import java.io.PrintWriter;
import java.io.Writer;
import java.sql.Connection;
import java.sql.DatabaseMetaData;
import java.sql.SQLException;
import java.sql.SQLFeatureNotSupportedException;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import static org.hamcrest.Matchers.sameInstance;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class MCPJdbcDatabaseProfileLoaderTest {

    @Test
    void assertLoadDataSourceWithUnsupportedCredentials() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                assertThrows(SQLFeatureNotSupportedException.class, () -> actual.getConnection("foo_user", "foo_password"));
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWithUnsupportedLogWriter() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                assertThrows(SQLFeatureNotSupportedException.class, actual::getLogWriter);
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWithUnsupportedSetLogWriter() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                assertThrows(SQLFeatureNotSupportedException.class, () -> actual.setLogWriter(new PrintWriter(Writer.nullWriter())));
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWithUnsupportedLoginTimeout() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                assertThrows(SQLFeatureNotSupportedException.class, actual::getLoginTimeout);
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWithUnsupportedSetLoginTimeout() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                assertThrows(SQLFeatureNotSupportedException.class, () -> actual.setLoginTimeout(1));
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWithUnsupportedParentLogger() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                assertThrows(SQLFeatureNotSupportedException.class, actual::getParentLogger);
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWrapper() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                assertTrue(actual.isWrapperFor(DataSource.class));
                assertFalse(actual.isWrapperFor(Connection.class));
                assertThat(actual.unwrap(DataSource.class), sameInstance(actual));
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWithUnsupportedWrapper() throws SQLException {
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource actual = invocation.getArgument(1, DataSource.class);
                SQLException actualException = assertThrows(SQLException.class, () -> actual.unwrap(Connection.class));
                assertThat(actualException.getMessage(), is("Unable to unwrap runtime database data source to `java.sql.Connection`."));
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoadDataSourceWithNonSQLConnectionFailure() throws SQLException {
        IllegalStateException expectedCause = new IllegalStateException("foo_invalid_config");
        RuntimeDatabaseConnectionException expected = RuntimeDatabaseConnectionException.invalidConfiguration("logic_db", expectedCause);
        Connection connection = mock(Connection.class);
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true, connection);
        when(runtimeDatabaseConfig.openConnection("logic_db")).thenReturn(connection).thenThrow(expected);
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> mocked = mockStatic(DatabaseIdentifierContextFactory.class)) {
            mocked.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                DataSource dataSource = invocation.getArgument(1, DataSource.class);
                SQLException actual = assertThrows(SQLException.class, dataSource::getConnection);
                assertThat(actual.getCause(), sameInstance(expected));
                return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
            });
            new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
        }
    }

    @Test
    void assertLoad() throws SQLException {
        DatabaseIdentifierContext expectedIdentifierContext = new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> ignoredFactory = mockStatic(DatabaseIdentifierContextFactory.class)) {
            ignoredFactory.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenReturn(expectedIdentifierContext);
            RuntimeDatabaseProfile actual =
                    new MCPJdbcDatabaseProfileLoader().load("logic_db", createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true));
            assertThat(actual.getDatabase(), is("logic_db"));
            assertThat(actual.getDatabaseType(), is("FixtureDB"));
            assertThat(actual.getDatabaseVersion(), is("1.0"));
            assertThat(actual.getTransactionCapability(), is(TransactionCapability.LOCAL_WITH_SAVEPOINT));
            assertThat(actual.getIdentifierContext(), is(expectedIdentifierContext));
        }
    }

    @Test
    void assertLoadWithoutTransaction() throws SQLException {
        Connection connection = mock(Connection.class);
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(
                SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", false, true, connection);
        DatabaseMetaData databaseMetaData = connection.getMetaData();
        try (MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata()) {
            RuntimeDatabaseProfile actual = new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
            assertThat(actual.getTransactionCapability(), is(TransactionCapability.NONE));
            verify(databaseMetaData, never()).supportsSavepoints();
        }
    }

    @Test
    void assertLoadWithoutSavepoint() throws SQLException {
        try (MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata()) {
            RuntimeDatabaseProfile actual =
                    new MCPJdbcDatabaseProfileLoader().load("logic_db", createRuntimeDatabaseConfiguration(SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, false));
            assertThat(actual.getTransactionCapability(), is(TransactionCapability.LOCAL));
        }
    }

    @Test
    void assertLoadIdentifierCasePolicyPerDatabase() throws SQLException {
        Connection firstConnection = mock(Connection.class);
        Connection secondConnection = mock(Connection.class);
        RuntimeDatabaseConfiguration firstRuntimeDatabase = createRuntimeDatabaseConfiguration(
                SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true, firstConnection);
        RuntimeDatabaseConfiguration secondRuntimeDatabase = createRuntimeDatabaseConfiguration(
                SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true, secondConnection);
        Map<String, RuntimeDatabaseConfiguration> runtimeDatabases = new LinkedHashMap<>(2, 1F);
        runtimeDatabases.put("first_db", firstRuntimeDatabase);
        runtimeDatabases.put("second_db", secondRuntimeDatabase);
        Map<Connection, DatabaseIdentifierContext> identifierContexts = Map.of(
                firstConnection, new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet()),
                secondConnection, new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newInsensitivePolicySet()));
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> ignoredFactory = mockStatic(DatabaseIdentifierContextFactory.class)) {
            ignoredFactory.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                try (Connection connection = invocation.getArgument(1, DataSource.class).getConnection()) {
                    return identifierContexts.get(connection);
                }
            });
            Map<String, RuntimeDatabaseProfile> actual = new MCPJdbcDatabaseProfileLoader().load(runtimeDatabases);
            assertFalse(actual.get("first_db").getIdentifierContext().matchesMetaData(IdentifierScope.TABLE, "phone", new IdentifierValue("Phone")));
            assertTrue(actual.get("second_db").getIdentifierContext().matchesMetaData(IdentifierScope.TABLE, "phone", new IdentifierValue("Phone")));
            verify(firstRuntimeDatabase, times(2)).openConnection("first_db");
            verify(firstRuntimeDatabase, never()).openConnection("second_db");
            verify(secondRuntimeDatabase, times(2)).openConnection("second_db");
            verify(secondRuntimeDatabase, never()).openConnection("first_db");
        }
    }

    @Test
    void assertLoadWhenIdentifierCasePolicyConnectionFails() throws SQLException {
        SQLException connectionFailure = new SQLException("connection unavailable");
        Connection profileConnection = mock(Connection.class);
        RuntimeDatabaseConfiguration runtimeDatabaseConfig = createRuntimeDatabaseConfiguration(
                SupportDatabaseTypeFactoryMocker.createJdbcUrl("FixtureDB"), "1.0", true, true, profileConnection);
        when(runtimeDatabaseConfig.openConnection("logic_db")).thenReturn(profileConnection)
                .thenThrow(RuntimeDatabaseConnectionException.connectionFailed("logic_db", connectionFailure));
        try (
                MockedStatic<DatabaseTypeFactory> ignored = SupportDatabaseTypeFactoryMocker.mockByConnectionMetadata();
                MockedStatic<DatabaseIdentifierContextFactory> ignoredFactory = mockStatic(DatabaseIdentifierContextFactory.class)) {
            ignoredFactory.when(() -> DatabaseIdentifierContextFactory.create(any(), any(DataSource.class))).thenAnswer(invocation -> {
                try (Connection ignoredConnection = invocation.getArgument(1, DataSource.class).getConnection()) {
                    return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newSensitivePolicySet());
                } catch (final SQLException ex) {
                    assertThat(ex, is(connectionFailure));
                    return new DatabaseIdentifierContext(IdentifierCasePolicyFactory.newInsensitivePolicySet());
                }
            });
            RuntimeDatabaseProfile actual = new MCPJdbcDatabaseProfileLoader().load("logic_db", runtimeDatabaseConfig);
            assertTrue(actual.getIdentifierContext().matchesMetaData(IdentifierScope.TABLE, "phone", new IdentifierValue("Phone")));
            verify(runtimeDatabaseConfig, times(2)).openConnection("logic_db");
        }
    }

    @Test
    void assertLoadWithInvalidJdbcUrl() {
        try (MockedStatic<DatabaseTypeFactory> mocked = mockStatic(DatabaseTypeFactory.class)) {
            ShardingSphereExternalException expectedCause = mock(ShardingSphereExternalException.class);
            mocked.when(() -> DatabaseTypeFactory.get(any(DatabaseMetaData.class))).thenThrow(expectedCause);
            RuntimeDatabaseConnectionException actual = assertThrows(RuntimeDatabaseConnectionException.class,
                    () -> new MCPJdbcDatabaseProfileLoader().load("logic_db", createRuntimeDatabaseConfiguration("jdbc:unknown:test", "8.0.32", true, true)));
            assertThat(actual.getCategory(), is(RuntimeDatabaseConnectionException.CATEGORY_INVALID_CONFIGURATION));
            assertThat(actual.getCause(), is(expectedCause));
        }
    }

    private RuntimeDatabaseConfiguration createRuntimeDatabaseConfiguration(final String jdbcUrl, final String databaseVersion,
                                                                            final boolean supportsTransaction, final boolean supportsSavepoint) throws SQLException {
        return createRuntimeDatabaseConfiguration(jdbcUrl, databaseVersion, supportsTransaction, supportsSavepoint, mock(Connection.class));
    }

    private RuntimeDatabaseConfiguration createRuntimeDatabaseConfiguration(final String jdbcUrl, final String databaseVersion,
                                                                            final boolean supportsTransaction, final boolean supportsSavepoint,
                                                                            final Connection connection) throws SQLException {
        RuntimeDatabaseConfiguration result = mock(RuntimeDatabaseConfiguration.class);
        DatabaseMetaData databaseMetaData = mock(DatabaseMetaData.class);
        when(result.openConnection(anyString())).thenReturn(connection);
        when(connection.getMetaData()).thenReturn(databaseMetaData);
        when(databaseMetaData.getURL()).thenReturn(jdbcUrl);
        when(databaseMetaData.getDatabaseProductVersion()).thenReturn(databaseVersion);
        when(databaseMetaData.supportsTransactions()).thenReturn(supportsTransaction);
        when(databaseMetaData.supportsSavepoints()).thenReturn(supportsSavepoint);
        return result;
    }
}

